create table if not exists public.buyer_profiles(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),first_name text not null,last_name text not null,email text,phone text,preferred_channel text not null,privacy_consent_at timestamptz not null,source text not null default 'buyer_funnel',unique(email),unique(phone));
create table if not exists public.buyer_searches(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),profile_id uuid not null references public.buyer_profiles(id) on delete cascade,reference text unique not null,project_type text,property_type text,communes text[] not null default '{}',budget_xpf bigint,budget_flexibility text,bedrooms integer,surface_min numeric,required_criteria text,wanted_criteria text,features text[] not null default '{}',purchase_timeline text,financing_status text,bank_approval boolean,seller_status text,seller_details jsonb not null default '{}',match_status text not null default 'not_configured' check(match_status in('not_configured','verified','unavailable','error')),verified_match_count integer,match_verified_at timestamptz,origin_data jsonb not null default '{}');
create table if not exists public.buyer_consents(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),profile_id uuid not null references public.buyer_profiles(id) on delete cascade,search_id uuid not null references public.buyer_searches(id) on delete cascade,kind text not null check(kind in('privacy','modelo_alert','minitaux_referral')),granted boolean not null,text_version text not null,granted_at timestamptz,unique(search_id,kind));
create table if not exists public.broker_referrals(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),profile_id uuid not null references public.buyer_profiles(id),search_id uuid not null references public.buyer_searches(id),broker_name text not null default 'Sulivan Langa-Mora — MiNiTAUX',consent_id uuid not null references public.buyer_consents(id),status text not null default 'pending_manual' check(status in('request_received','pending_manual','submitted','accepted','in_progress','successful','unsuccessful','commission_check','commission_paid','failed')),actelo_reference text,submitted_at timestamptz,last_error text,commission_eligible boolean,commission_expected_xpf integer,commission_received_xpf integer,unique(profile_id,search_id));
create table if not exists public.buyer_service_tasks(id uuid primary key default gen_random_uuid(),created_at timestamptz not null default now(),search_id uuid not null references public.buyer_searches(id) on delete cascade,kind text not null check(kind in('declare_actelo','activate_modelo_alert','create_seller_opportunity','sync_kw_impact','callback')),status text not null default 'pending' check(status in('pending','in_progress','completed','failed')),payload jsonb not null default '{}',completed_at timestamptz);
create table if not exists public.buyer_funnel_events(id bigint generated always as identity primary key,created_at timestamptz not null default now(),session_id uuid not null,event_name text not null,page_path text,traffic_source text,metadata jsonb not null default '{}');
create index if not exists buyer_search_profile_idx on public.buyer_searches(profile_id,created_at desc);create index if not exists buyer_tasks_status_idx on public.buyer_service_tasks(status,kind);create index if not exists broker_referrals_status_idx on public.broker_referrals(status,created_at desc);
alter table public.buyer_profiles enable row level security;alter table public.buyer_searches enable row level security;alter table public.buyer_consents enable row level security;alter table public.broker_referrals enable row level security;alter table public.buyer_service_tasks enable row level security;alter table public.buyer_funnel_events enable row level security;
create policy "buyer admins profiles" on public.buyer_profiles for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins searches" on public.buyer_searches for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins consents" on public.buyer_consents for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins referrals" on public.broker_referrals for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins tasks" on public.buyer_service_tasks for all to authenticated using(public.is_foncier_admin()) with check(public.is_foncier_admin());create policy "buyer admins events" on public.buyer_funnel_events for select to authenticated using(public.is_foncier_admin());
